function fresh(S){
 const first=`<div class="d-first"><h3>Start with what you have.</h3><div class="d-ways"><button data-act="capture:subject">${icon('mic')}<b>A recording</b><span>Record now, or add one you have.</span></button><button data-act="capture:subject">${icon('note')}<b>A note or a link</b><span>A thought, a page, a video.</span></button><button data-act="capture:subject">${icon('photo')}<b>Photographs</b><span>From this device or the Library.</span></button></div><p class="d-meta">You do not have to know what this will become. Or begin with words: <button class="d-link" data-act="go:write">Start writing${icon('chev')}</button></p></div>`;
 const later=(t,b='')=>`<p class="d-later">${t}</p>${b}`;
 requestAnimationFrame(spy);
 return `<div class="d-subject fresh">${spine(S,true)}<main class="d-main">${stepper(0)}${plan(S,true)}${band('gather','Gather','What goes in',first,'now',`<span class="d-here">Start here</span>`)}
 ${band('research','Research','What you will learn',later('Research opens topics by itself once there is something to learn from. You can also begin with a question.',`<div class="d-row"><button class="btn" data-act="capture:subject">${icon('ask')}Ask a first question</button></div>`))}
 ${band('create','Create','What you will make',later('The Article, and any Carousel, Post or notes made from it, appear here as they will look.'))}
 ${band('share','Share','Where it goes',later('Who is shown and whether they agree, what your audience sees, and what has gone out.'))}</main></div>${K.newSheet()}`;}
/* jump to a section, and show which one is in view */
K.on('jump',id=>{const el=document.getElementById('st-'+id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'});});
function spy(){const bands=[...document.querySelectorAll('[data-band]')];if(!bands.length)return;let cur=bands[0];for(const b of bands)if(b.getBoundingClientRect().top<=160)cur=b;
 if(innerHeight+scrollY>=document.documentElement.scrollHeight-4)cur=bands[bands.length-1];
 document.querySelectorAll('[data-st]').forEach(x=>x.classList.toggle('inview',x.dataset.st===cur.dataset.band));bands.forEach(b=>b.classList.toggle('inview',b===cur));}
addEventListener('scroll',spy,{passive:true});

/* ---------- research: one topic, read first, one decision at a time ---------- */
const SAY=[['Three weeks of shade keeps the leaf sweet and the bitterness down.','agree','Agreed',6,0],['The leaf is ready by look and touch, not by counting days.','agree','Agreed',4,0],['Straw gives a better leaf than netting.','split','They disagree',3,2],['Shading too long weakens the bush for next year.','warn','A warning',2,0],['Straw feeds the soil it shades as it falls apart.','one','One voice',1,0]];
function topic(S){const tab=S.ui.tab||'read',find=S.ui.find,rul=S.ui.ruling,left=(find?0:1)+(rul?0:1);
 const meter=(f,a)=>`<span class="d-meter" aria-hidden="true">${'<i class="f"></i>'.repeat(f)}${'<i class="a"></i>'.repeat(a)}</span>`;
 const read=`<article class="d-page d-read"><p class="d-crumbs"><button data-act="go:group">Tea: growing</button><span>/</span>${origin('talk','Mrs. Oda’s recording, 6 Nov')}<span>·</span>used in ${esc(SUB.short)}</p><h1>Shading tea</h1>
 <p class="d-lead">Shading starves the bush of sun for about three weeks before picking, so the leaf keeps the sweetness that light would turn bitter.</p>
 <p>The old way, <dfn>honzu</dfn>, lays reed screens over a frame of poles and scatters straw on top by hand. Most gardens now hang black netting, which one person can put up in a morning. Growers agree on the timing. Where they part is on whether the cover itself changes the tea, and that is what your morning with Mrs. Oda was about.</p>
 <h2>What people say</h2>
 <ul class="d-say">${SAY.map(([t,k,w,f,a])=>`<li class="${k}"><p>${esc(t)}</p><span>${meter(f,a)}${w}</span></li>`).join('')}</ul>
 <h2>In her words</h2>
 <ol class="d-talk acct">${K.transcript.filter(l=>l.who!=='You').slice(1).map(l=>`<li><p class="speech">“${esc(l.text)}”</p><small>Mrs. Oda · ${l.t}</small></li>`).join('')}</ol>
 <div class="d-take"><p class="d-label">${mark('yours')}</p><h2>In one line, what do you take from this?</h2><span class="d-field tall">She is not counting anything. The shade is a way of slowing down so she can look.</span><p class="d-meta">Only you write here. That is all Research asks of you.</p></div></article>`;
 const card=!find?`<article class="d-dec"><p class="d-label">1 of 2 · a new find</p><h2>Keep this as a source?</h2><p class="d-dec-s">An article that came back while looking for growers who moved to netting.</p><blockquote>“The netting rows were ready four days sooner, and in the cup we argued about it all afternoon.”<small>A season under two covers</small></blockquote><div class="d-row"><button class="btn pri lg" data-act="ui:find:kept">Keep</button><button class="btn lg" data-act="ui:find:rejected">Turn down</button><button class="btn lg ghost" data-act="ui:find:skipped">Not now</button></div></article>`
  :!rul?`<article class="d-dec"><p class="d-label">2 of 2 · they disagree</p><h2>Straw or netting: do you want to say where you stand?</h2><p class="d-dec-s">They are talking about different fields. Three who back straw pick small gardens by hand; two who dispute it harvest large fields by machine.</p><span class="d-field tall">Straw matters for small gardens picked by hand.</span><div class="d-row"><button class="btn pri lg" data-act="ui:ruling:made">Keep that as my view</button><button class="btn lg ghost" data-act="ui:ruling:skipped">Not now</button></div><p class="d-meta">You never have to. The Article can simply say that growers disagree.</p></article>`
  :`<article class="d-dec done">${icon('check')}<h2>Nothing else needs you here.</h2><p class="d-dec-s">${find==='kept'?'The find was kept.':find==='rejected'?'The find was turned down and will not come back.':'The find waits.'} ${rul==='made'?'Your view is saved in your own words.':'The disagreement is left open.'}</p><div class="d-row"><button class="btn lg" data-act="ui:${rul?'ruling:'+rul:'find:'+find}">${icon('undo')}Undo the last one</button><button class="btn lg pri" data-act="go:write">Back to the writing${icon('right')}</button></div></article>`;
 const srcs=`<article class="d-page d-read"><div class="d-row"><h1 class="small">Where this comes from</h1><span class="sp"></span><button class="btn" data-act="noop">${icon('plus')}Add a source</button></div><p class="d-sub">9 sources. Each counts once, however long it is.</p><ul class="d-src-l wide">${[['mic','Kirihara garden walk','Recording · Mrs. Oda','theirs'],['note','Your three notes','Kept apart from the evidence','yours'],['book','The Shaded Leaf','Book · 2011','evidence'],['note','Why shade matters','Article','evidence'],['film','A grower’s talk','Video · 48 min','evidence'],['layers','Tea Atlas: Shading','Your Atlas','evidence']].map(([ic,n,m,o])=>`<li><button data-act="noop">${icon(ic)}<span><b>${esc(n)}</b><small>${esc(m)}</small></span>${mark(o)}</button></li>`).join('')}<li class="more"><button data-act="noop">3 more sources</button></li></ul>
 <h2>How Claude looked</h2><p class="d-sub">Five viewpoints. The last one is always included.</p><ul class="d-angles"><li>Growers who shade with straw</li><li>Growers who moved to netting</li><li>What the plant does in shade</li><li>How the method began</li><li class="req">People who tried it and it failed</li></ul><div class="d-row"><button class="btn" data-act="noop">${icon('plus')}Add a viewpoint</button><button class="btn" data-act="noop">Look again</button></div></article>`;
 return `${top(S)}<div class="d-bar"><button class="d-backto" data-act="go:research">${icon('back')}<span>Research</span></button><div class="d-tabs">${[['read','Read'],['decide',left?`Decide · ${left}`:'Decide'],['sources','Sources · 9']].map(([k,l])=>`<button data-act="set:tab:${k}"${tab===k?' aria-current="page"':''}>${l}</button>`).join('')}</div><span class="sp"></span><button class="btn" data-act="noop" data-keep>${icon('play')}<span>Listen · 6 min</span></button></div>
 <div class="d-topic1">${tab==='decide'?`<div class="d-decwrap">${card}</div>`:tab==='sources'?srcs:read}</div>${phonebar(S)}`;}

