 <ul>${src.map(([ic,n,m,on])=>`<li><button data-act="noop" aria-pressed="${on?'true':'false'}"><i class="d-tick" aria-hidden="true"></i>${icon(ic)}<span><b>${esc(n)}</b><small>${esc(m)}</small></span></button></li>`).join('')}<li class="more"><button data-act="noop">23 more sources</button></li></ul>
